    elif applicant.parents_income == 'low':
        pass

    # Check parents' degree
    if applicant.parents_degree in ['bachelor', 'master', 'PhD']:
        score += 1

    # Check gender (female gets 0.5 points)
    if applicant.gender == 'female':
        score += 0.5

    # Check nationality (Francophone country)
    if applicant.nationality in ['France', 'Canada (French speaking)', 'Belgium', 'Switzerland', 'Luxembourg', 'Monaco']:
        score += 1

